<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api} from '../api';
const props=defineProps<{owner:boolean}>();const data=ref<any>(null),form=ref<any>({}),reason=ref(''),busy=ref(false),error=ref(''),notice=ref('');
async function load(){busy.value=true;error.value='';try{data.value=await api('/builder/budget');form.value={...data.value.policy}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';notice.value='';try{await api('/builder/budget',{dailyCostLimit:form.value.dailyCostLimit,dailyTokenLimit:form.value.dailyTokenLimit,perCallCostLimit:form.value.perCallCostLimit,perCallTokenLimit:form.value.perCallTokenLimit,maxConcurrentCalls:form.value.maxConcurrentCalls,reason:reason.value},'PUT');notice.value='预算已保存；已经开始的调用记录和预留继续保留。';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load);
</script>
<template><section class="card" aria-label="建库预算"><h2>建库预算与名额</h2><p class="muted">每天按 UTC 日期计算。结果不明的额度跨日保留，已开始但未确认结束的调用继续占用名额。当前为本地模拟流程。</p><button :disabled="busy" @click="load">刷新预算</button><p v-if="error" role="alert" class="warning">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="data"><p>已结算或预留：{{data.state.costCommitted}} USD / {{data.policy.dailyCostLimit}} USD；Token：{{data.state.tokensCommitted}} / {{data.policy.dailyTokenLimit}}</p><p>占用名额 {{data.state.activeCalls}} / {{data.policy.maxConcurrentCalls}} · 待核对 {{data.state.unresolvedCalls}} · 超出报价待核对 {{data.state.overrunCalls}}</p><p v-if="data.state.unboundedUnknownCalls" class="warning">有旧调用缺少可验证的预算上限，需要核对后才能开始有费用的调用。</p><form v-if="props.owner" class="form-grid" @submit.prevent="save"><label>每日费用上限（USD）<input v-model="form.dailyCostLimit" type="number" min="0" step="0.000001" required></label><label>单次费用上限（USD）<input v-model="form.perCallCostLimit" type="number" min="0" step="0.000001" required></label><label>每日 Token 上限<input v-model.number="form.dailyTokenLimit" type="number" min="0" max="1000000000000" step="1" required></label><label>单次 Token 上限<input v-model.number="form.perCallTokenLimit" type="number" min="0" max="1000000000000" step="1" required></label><label>同时处理上限<input v-model.number="form.maxConcurrentCalls" type="number" min="1" max="10" required></label><label>调整依据<textarea v-model="reason" maxlength="4000" required></textarea></label><button :disabled="busy" type="submit">保存调用预算</button></form></template></section></template>
